describe('File Upload - Title and Description', () => {
  beforeEach(() => {
    cy.visit('/file-upload');
  });

  it('should successfully set title and description for uploaded file', () => {
    // Upload a file
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/sample.pdf', { force: true });

    // Verify file is selected
    cy.get('[data-testid="file-name"]').should('contain', 'sample.pdf');

    // Set title and description
    cy.get('[data-testid="file-title-input"]').type('Project Report Q3');
    cy.get('[data-testid="file-description-input"]').type('Detailed report on Q3 project milestones and achievements.');

    // Verify title and description are set
    cy.get('[data-testid="file-title-display"]').should('contain', 'Project Report Q3');
    cy.get('[data-testid="file-description-display"]').should('contain', 'Detailed report on Q3 project milestones and achievements.');

    // Submit the file
    cy.get('[data-testid="upload-button"]').click();

    // Verify success message
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'File uploaded successfully');

    // Verify file appears in list
    cy.get('[data-testid="uploaded-file-item"]').should('be.visible');
    cy.get('[data-testid="uploaded-file-item"]').should('contain', 'Project Report Q3');
  });

  it('should handle empty title and description fields with validation', () => {
    // Upload a file
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/sample.pdf', { force: true });

    // Attempt to submit without filling title or description
    cy.get('[data-testid="upload-button"]').click();

    // Verify validation error appears for title
    cy.get('[data-testid="title-error-message"]').should('be.visible').should('contain', 'Title is required');

    // Verify validation error appears for description
    cy.get('[data-testid="description-error-message"]').should('be.visible').should('contain', 'Description is required');

    // Verify file is not uploaded
    cy.get('[data-testid="success-message"]').should('not.exist');

    // Verify file remains in input field
    cy.get('[data-testid="file-name"]').should('contain', 'sample.pdf');

    // Clear errors and fill only title
    cy.get('[data-testid="title-error-message"]').should('not.exist');
    cy.get('[data-testid="description-error-message"]').should('not.exist');
    cy.get('[data-testid="file-title-input"]').clear().type('Only Title');

    // Attempt to submit again
    cy.get('[data-testid="upload-button"]').click();

    // Verify description error still exists
    cy.get('[data-testid="description-error-message"]').should('be.visible').should('contain', 'Description is required');

    // Verify file is not uploaded
    cy.get('[data-testid="success-message"]').should('not.exist');
  });
});
